INSERT INTO lf_ops.nucleo_familia_vocabulario(familia,hecho,origen) VALUES
('PAYMENTS_CHECKOUT','m1_resumen_checkout_en_presentacion','CURADO'),
('PAYMENTS_CHECKOUT','m1_resumen_checkout_corresponde_seleccion','CURADO'),
('PAYMENTS_CHECKOUT','m1_solicitud_cancelacion_recurrencia','CURADO'),
('PAYMENTS_CHECKOUT','m1_cancelacion_recurrencia_permitida_sin_penalidad','CURADO'),
('PAYMENTS_CHECKOUT','evidencia_autoritativa_pago','CURADO'),
('PAYMENTS_CHECKOUT','estado_pago_normalizado','CURADO'),
('PAYMENTS_CHECKOUT','m1_destinatario_recibo_real_validado','CURADO'),
('PAYMENTS_CHECKOUT','m1_habilitacion_produccion_pago','CURADO'),
