('IDEMPOTENCY_CONCURRENCY','peticion_idempotente_equivalente','CURADO'),
('IDEMPOTENCY_CONCURRENCY','edad_clave_idempotencia','CURADO') ON CONFLICT DO NOTHING;
DO $m1$
DECLARE p jsonb; g jsonb; e jsonb; before_legacy jsonb; before_other jsonb; before_versions jsonb; before_history jsonb; before_effective jsonb; n int := 0; bad jsonb;
BEGIN
 SELECT jsonb_agg(to_jsonb(r) ORDER BY id) INTO before_legacy FROM lf_ops.v_reglas_compat_v1 r;
 SELECT jsonb_agg(to_jsonb(r) ORDER BY codigo) INTO before_other FROM lf_ops.nucleo_reglas r;
 SELECT jsonb_agg(to_jsonb(v) ORDER BY regla,version) INTO before_versions FROM lf_ops.nucleo_regla_versiones v;
 SELECT jsonb_agg(to_jsonb(d) ORDER BY regla,version) INTO before_history FROM lf_ops.nucleo_deprecaciones d;
 SELECT jsonb_agg(jsonb_build_object('nodo',n.codigo,'r',to_jsonb(e)) ORDER BY n.codigo,e.regla) INTO before_effective FROM lf_ops.nucleo_nodos n CROSS JOIN LATERAL lf_ops.nucleo_reglas_efectivas_v1(n.codigo,now()) e;
 FOR p IN SELECT value FROM jsonb_array_elements($packs$[{"tipo":"NUEVA","codigo":"M1-C01","clave":"resumen_checkout_consolidado","titulo":"Resumen único de ofertas y modalidades","descripcion":"En la presentación del resumen de checkout, mostrar una sola consolidación de ofertas y modalidades seleccionadas, sin perder ni alterar la selección. Bloquear presentación como válida si el resumen no corresponde íntegramente a la selección. No calcula precio final ni comisiones (M1-D01).","familia":"PAYMENTS_CHECKOUT","naturaleza":"CONDUCTA","autoridad":"LEG-PRODUCTO","dueno":"PRODUCTO","alcance":"CLIENT_PAYMENTS","modo":"HEREDA","clase":"PANTALLA","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m1_resumen_checkout_en_presentacion"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m1_resumen_checkout_corresponde_seleccion"},"der":{"lit":false}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/155","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m1_resumen_checkout_en_presentacion":true,"m1_resumen_checkout_corresponde_seleccion":false},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m1_resumen_checkout_en_presentacion":true,"m1_resumen_checkout_corresponde_seleccion":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m1_resumen_checkout_en_presentacion":false,"m1_resumen_checkout_corresponde_seleccion":false},"esperado":false}]},{"tipo":"NUEVA","codigo":"M1-C02","clave":"cancelacion_recurrencia_sin_penalidad","titulo":"Cancelación de recurrencia sin penalidad","descripcion":"En la gestión de un plan con cobro recurrente, permitir al cliente solicitar cancelación desde Mis operaciones sin penalidad ni declarar liquidada la deuda; impedir aplicar penalidad o rechazar la cancelación por esa causa. El aviso previo en checkout queda residual UI; disponibilidad de Yape posterior por investigar (M1-D02).","familia":"PAYMENTS_CHECKOUT","naturaleza":"CONDUCTA","autoridad":"LEG-PRODUCTO","dueno":"PRODUCTO","alcance":"BACKEND","modo":"HEREDA","clase":"BACKEND","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m1_solicitud_cancelacion_recurrencia"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m1_cancelacion_recurrencia_permitida_sin_penalidad"},"der":{"lit":false}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/277,289","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m1_solicitud_cancelacion_recurrencia":true,"m1_cancelacion_recurrencia_permitida_sin_penalidad":false},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m1_solicitud_cancelacion_recurrencia":true,"m1_cancelacion_recurrencia_permitida_sin_penalidad":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m1_solicitud_cancelacion_recurrencia":false,"m1_cancelacion_recurrencia_permitida_sin_penalidad":false},"esperado":false}]},{"tipo":"NUEVA","codigo":"M1-C03","clave":"recibo_correo_real","titulo":"Recibo únicamente al correo real validado","descripcion":"Bloquear la emisión del recibo si no existe confirmación autoritativa PAYMENT_CONFIRMED o el destinatario no es el correo real registrado y validado del cliente. Mantener customer_email separado de niubiz_technical_email (PAGOS/NIUBIZ_EMAIL_TEMPLATE y PAGOS/NIUBIZ_EMAIL_DOMAIN); registrar incidencia si falta correo real, sin fallback técnico o genérico. Rebote técnico no confirma pago.","familia":"PAYMENTS_CHECKOUT","naturaleza":"CONDUCTA","autoridad":"LEG-REVISION_FUNCIONAL","dueno":"PRODUCTO","alcance":"BACKEND","modo":"HEREDA","clase":"BACKEND","condicion":{"op":"o","izq":{"op":"=","izq":{"hecho":"evidencia_autoritativa_pago"},"der":{"lit":false}},"der":{"op":"o","izq":{"op":"!=","izq":{"hecho":"estado_pago_normalizado"},"der":{"lit":"PAYMENT_CONFIRMED"}},"der":{"op":"=","izq":{"hecho":"m1_destinatario_recibo_real_validado"},"der":{"lit":false}}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/13126","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"evidencia_autoritativa_pago":true,"estado_pago_normalizado":"PAYMENT_CONFIRMED","m1_destinatario_recibo_real_validado":false},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"evidencia_autoritativa_pago":true,"estado_pago_normalizado":"PAYMENT_CONFIRMED","m1_destinatario_recibo_real_validado":true},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"evidencia_autoritativa_pago":false,"estado_pago_normalizado":"PAYMENT_CONFIRMED","m1_destinatario_recibo_real_validado":true},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"evidencia_autoritativa_pago":true,"estado_pago_normalizado":"PAYMENT_PENDING_CONFIRMATION","m1_destinatario_recibo_real_validado":true},"esperado":true}]},{"tipo":"NUEVA","codigo":"M1-C04","clave":"sandbox_credenciales_pago","titulo":"Sandbox y credenciales separadas","descripcion":"Bloquear habilitación de producción del checkout cuando el flujo completo no tenga evidencia satisfactoria de pruebas en sandbox Niubiz o las credenciales de ambientes no estén separadas. No autoriza producción ni afirma capacidad de proveedor.","familia":"PAYMENTS_CHECKOUT","naturaleza":"CONDUCTA","autoridad":"LEG-TECNICO","dueno":"PRODUCTO","alcance":"BACKEND","modo":"HEREDA","clase":"BACKEND","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m1_habilitacion_produccion_pago"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"=","izq":{"hecho":"m1_sandbox_checkout_certificado"},"der":{"lit":false}},"der":{"op":"=","izq":{"hecho":"m1_credenciales_ambientes_separadas"},"der":{"lit":false}}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/229","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m1_habilitacion_produccion_pago":true,"m1_sandbox_checkout_certificado":false,"m1_credenciales_ambientes_separadas":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m1_habilitacion_produccion_pago":true,"m1_sandbox_checkout_certificado":true,"m1_credenciales_ambientes_separadas":true},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"m1_habilitacion_produccion_pago":true,"m1_sandbox_checkout_certificado":true,"m1_credenciales_ambientes_separadas":false},"esperado":true}]},{"tipo":"NUEVA","codigo":"M1-C05","clave":"onboarding_offline_conservacion","titulo":"Conservación offline de captura inicial","descripcion":"En las pantallas iniciales de onboarding identificadas como PANTALLA-1 y PANTALLA-2, ante pérdida de conexión, conservar localmente lo escrito y mostrar aviso de desconexión y conservación de datos. No afirmar guardado si no existe evidencia de persistencia. Checkout permanece gobernado por REG_TEC_007 V2.","familia":"BROWSER_PLATFORM","naturaleza":"CONDUCTA","autoridad":"LEG-TECNICO","dueno":"PRODUCTO","alcance":"CLIENT_ONBOARDING","modo":"HEREDA","clase":"PANTALLA","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m1_onboarding_paso_captura_inicial"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"conexion_disponible"},"der":{"lit":false}}},"efecto":"EXIGIR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/183","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m1_onboarding_paso_captura_inicial":true,"conexion_disponible":false},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m1_onboarding_paso_captura_inicial":true,"conexion_disponible":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m1_onboarding_paso_captura_inicial":false,"conexion_disponible":false},"esperado":false}]},{"tipo":"NUEVA","codigo":"M1-C06","clave":"idempotencia_onboarding_submit","titulo":"Idempotencia submit inicial onboarding","descripcion":"En el submit inicial de onboarding exigir clave UUID v4 generada en cliente, header X-Idempotency-Key. Ante reenvío equivalente por timeout o doble clic dentro de AUTH/IDEMPOTENCY_KEY_VALIDITY_MINUTES, recuperar resultado anterior sin duplicar operación. El valor procede de public.lf_global_config vía public.lf_auth_config_integer_v1; fuera de ventana no autoriza segundo submit por sí solo. Checkout permanece en REG_TEC_009 V3 candidata.","familia":"IDEMPOTENCY_CONCURRENCY","naturaleza":"CONDUCTA","autoridad":"LEG-TECNICO","dueno":"PRODUCTO","alcance":"BACKEND","modo":"HEREDA","clase":"BACKEND","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m1_operacion_submit_onboarding_inicial"},"der":{"lit":true}},"der":{"op":"y","izq":{"op":"=","izq":{"hecho":"clave_idempotencia_repetida"},"der":{"lit":true}},"der":{"op":"y","izq":{"op":"=","izq":{"hecho":"peticion_idempotente_equivalente"},"der":{"lit":true}},"der":{"op":"<","izq":{"hecho":"edad_clave_idempotencia"},"der":{"param":"AUTH.IDEMPOTENCY_KEY_VALIDITY_MINUTES"}}}}},"efecto":"PERMITIR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/185","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"BAJO_EL_LIMITE","entrada":{"m1_operacion_submit_onboarding_inicial":true,"clave_idempotencia_repetida":true,"peticion_idempotente_equivalente":true,"edad_clave_idempotencia":{"param":"AUTH.IDEMPOTENCY_KEY_VALIDITY_MINUTES","mas":-1}},"esperado":true},{"casuistica":"EN_EL_LIMITE","entrada":{"m1_operacion_submit_onboarding_inicial":true,"clave_idempotencia_repetida":true,"peticion_idempotente_equivalente":true,"edad_clave_idempotencia":{"param":"AUTH.IDEMPOTENCY_KEY_VALIDITY_MINUTES","mas":0}},"esperado":false},{"casuistica":"SOBRE_EL_LIMITE","entrada":{"m1_operacion_submit_onboarding_inicial":true,"clave_idempotencia_repetida":true,"peticion_idempotente_equivalente":true,"edad_clave_idempotencia":{"param":"AUTH.IDEMPOTENCY_KEY_VALIDITY_MINUTES","mas":1}},"esperado":false}]}]$packs$::jsonb) LOOP
   g:=lf_ops.nucleo_regla_proponer_v1(p,true);
   RAISE NOTICE 'M1_PROPOSE % %',p->>'codigo',g;
   IF g->>'resultado' IS DISTINCT FROM 'CANDIDATA' THEN RAISE EXCEPTION 'M1_PROPOSAL_REJECTED % %',p->>'codigo',g; END IF;
   e:=lf_ops.nucleo_regla_evaluar_v1(p->>'codigo',true);
   RAISE NOTICE 'M1_EVALUATE % %',p->>'codigo',e;
   IF e->'componentes'->>'profundidad' IS DISTINCT FROM '1.000' AND (e->'componentes'->>'profundidad')::numeric IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'M1_DEPTH % %',p->>'codigo',e; END IF;
   IF e->>'decision' IS DISTINCT FROM 'BLOQUEADA' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(e->'motivos') t WHERE t->>'dimension'='JUICIO') THEN RAISE EXCEPTION 'M1_EXPECTED_UNJUDGED % %',p->>'codigo',e; END IF;
   IF NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_reglas r JOIN lf_ops.nucleo_regla_versiones v ON v.regla=r.codigo WHERE r.codigo=p->>'codigo' AND r.estado='CANDIDATA' AND r.regla_legacy_id IS NULL AND v.estado='CANDIDATA' AND v.publicada_desde IS NULL AND v.exigible_desde IS NULL) THEN RAISE EXCEPTION 'M1_STATE %',p->>'codigo'; END IF;
   n:=n+1;
 END LOOP;
 -- Negative: numeric percentage literal in condition, deliberately not allowed.
 p:=($packs${"tipo":"NUEVA","codigo":"M1-C01","clave":"resumen_checkout_consolidado","titulo":"Resumen único de ofertas y modalidades","descripcion":"En la presentación del resumen de checkout, mostrar una sola consolidación de ofertas y modalidades seleccionadas, sin perder ni alterar la selección. Bloquear presentación como válida si el resumen no corresponde íntegramente a la selección. No calcula precio final ni comisiones (M1-D01).","familia":"PAYMENTS_CHECKOUT","naturaleza":"CONDUCTA","autoridad":"LEG-PRODUCTO","dueno":"PRODUCTO","alcance":"CLIENT_PAYMENTS","modo":"HEREDA","clase":"PANTALLA","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m1_resumen_checkout_en_presentacion"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m1_resumen_checkout_corresponde_seleccion"},"der":{"lit":false}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/155","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m1_resumen_checkout_en_presentacion":true,"m1_resumen_checkout_corresponde_seleccion":false},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m1_resumen_checkout_en_presentacion":true,"m1_resumen_checkout_corresponde_seleccion":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m1_resumen_checkout_en_presentacion":false,"m1_resumen_checkout_corresponde_seleccion":false},"esperado":false}]}$packs$::jsonb || jsonb_build_object('codigo','M1-NEG-COMISION','clave','m1_negative_commission','titulo','Mutante comisión fija','condicion',jsonb_build_object('op','=', 'izq',jsonb_build_object('lit',3.5),'der',jsonb_build_object('lit',3.5))));
 bad:=lf_ops.nucleo_regla_proponer_v1(p,true);
 IF bad->>'resultado' IS DISTINCT FROM 'RECHAZADA' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(bad->'controles') t WHERE t->>'control'='Sin datos fijos' AND t->>'ok'='false') THEN RAISE EXCEPTION 'M1_FIXED_COMMISSION_NOT_REJECTED %',bad; END IF;
 RAISE NOTICE 'M1_NEGATIVE_FIXED_COMMISSION %',bad;
 IF n<>6 OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY id) FROM lf_ops.v_reglas_compat_v1 r) IS DISTINCT FROM before_legacy OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY codigo) FROM lf_ops.nucleo_reglas r WHERE codigo NOT LIKE 'M1-C0%') IS DISTINCT FROM before_other OR (SELECT jsonb_agg(to_jsonb(v) ORDER BY regla,version) FROM lf_ops.nucleo_regla_versiones v WHERE regla NOT LIKE 'M1-C0%') IS DISTINCT FROM before_versions OR (SELECT jsonb_agg(to_jsonb(d) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones d) IS DISTINCT FROM before_history OR (SELECT jsonb_agg(jsonb_build_object('nodo',n.codigo,'r',to_jsonb(e)) ORDER BY n.codigo,e.regla) FROM lf_ops.nucleo_nodos n CROSS JOIN LATERAL lf_ops.nucleo_reglas_efectivas_v1(n.codigo,now()) e) IS DISTINCT FROM before_effective THEN RAISE EXCEPTION 'M1_UNAUTHORIZED_DRIFT'; END IF;
 RAISE NOTICE 'M1_PASS 6/6 candidate-only; existing rules and effective reads unchanged';
END $m1$;
COMMIT;
